[patterns/application/api-microservices/PTN-APP-API-021-async-request-reply-pattern.md#phase-2-implementation-week-3-6]

#### Phase 2: Implementation (Week 3-6)

**Step 1: Implement Request Handler**

Create API endpoint accepting async requests:

```csharp
[ApiController]
[Route("api/providers")]
public class ProviderCredentialingController : ControllerBase
{
    private readonly IOperationStore _operationStore;
    private readonly IServiceBusClient _serviceBus;
    private readonly ILogger<ProviderCredentialingController> _logger;

    [HttpPost("credentialing")]
    [ProducesResponseType(typeof(OperationAcceptedResponse), StatusCodes.Status202Accepted)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> SubmitCredentialingApplication(
        [FromBody] CredentialingApplication application,
        [FromHeader(Name = "X-Idempotency-Key")] string? idempotencyKey = null,
        [FromHeader(Name = "X-Callback-Url")] string? callbackUrl = null)
    {
        // Validate input
        var validationResult = await _validator.ValidateAsync(application);
        if (!validationResult.IsValid)
            return BadRequest(validationResult.Errors);

        // Generate or retrieve operation ID (idempotency)
        var operationId = idempotencyKey ?? Guid.NewGuid().ToString();

        // Check for existing operation (idempotency)
        var existingOperation = await _operationStore.GetAsync(operationId);
        if (existingOperation != null)
        {
            _logger.LogInformation($\"Returning existing operation {operationId} (idempotency)\");
            return AcceptedAtAction(
                nameof(OperationsController.GetOperationStatus),
                \"Operations\",
                new { operationId },
                new OperationAcceptedResponse
                {
                    OperationId = operationId,
                    Status = existingOperation.Status.ToString(),
                    StatusUrl = $\"/api/operations/{operationId}\"
                });
        }

        // Create operation status record
        var operation = new OperationStatus
        {
            OperationId = operationId,
            Status = OperationState.Accepted,
            CreatedAt = DateTime.UtcNow,
            Requestor = User.Identity.Name ?? \"anonymous\",
            CallbackUrl = callbackUrl,
            ExpiresAt = DateTime.UtcNow.AddDays(3),
            Metadata = new Dictionary<string, string>
            {
                [\"OperationType\"] = \"ProviderCredentialing\",
                [\"ApplicationId\"] = application.Id.ToString()
            }
        };

        await _operationStore.CreateAsync(operation);

        // Enqueue message for background processing
        var message = new ServiceBusMessage(JsonSerializer.Serialize(new
        {
            OperationId = operationId,
            OperationType = \"ProviderCredentialing\",
            Payload = application
        }))
        {
            MessageId = operationId,
            ContentType = \"application/json\",
            Subject = \"ProviderCredentialing\"
        };

        await _serviceBus.SendMessageAsync(\"credentialing-queue\", message);

        _logger.LogInformation($\"Created async operation {operationId} for credentialing application {application.Id}\");

        // Return 202 Accepted with operation details
        Response.Headers.Add(\"Location\", $\"/api/operations/{operationId}\");

        return AcceptedAtAction(
            nameof(OperationsController.GetOperationStatus),
            \"Operations\",
            new { operationId },
            new OperationAcceptedResponse
            {
                OperationId = operationId,
                Status = \"Accepted\",
                StatusUrl = $\"/api/operations/{operationId}\",
                Links = new Dictionary<string, LinkObject>
                {
                    [\"self\"] = new LinkObject { Href = $\"/api/operations/{operationId}\" }
                }
            });
    }
}
```

**Step 2: Implement Status Endpoint**

```csharp
[ApiController]
[Route(\"api/operations\")]
public class OperationsController : ControllerBase
{
    private readonly IOperationStore _operationStore;

    [HttpGet(\"{operationId}\")]
    [ProducesResponseType(typeof(OperationStatus), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetOperationStatus(string operationId)
    {
        var operation = await _operationStore.GetAsync(operationId);

        if (operation == null)
            return NotFound(new { Error = \"Operation not found\" });

        // Verify requestor (only creator can check status)
        if (operation.Requestor != User.Identity.Name && !User.IsInRole(\"Admin\"))
            return Forbid();

        // Add result URL if completed
        if (operation.Status == OperationState.Completed)
        {
            operation.ResultUrl = $\"/api/operations/{operationId}/result\";
        }

        // Set appropriate cache headers
        if (operation.Status == OperationState.Completed || operation.Status == OperationState.Failed)
        {
            Response.Headers.Add(\"Cache-Control\", \"private, max-age=3600\");
        }
        else
        {
            Response.Headers.Add(\"Cache-Control\", \"no-cache\");
        }

        return Ok(operation);
    }

    [HttpGet(\"{operationId}/result\")]
    [ProducesResponseType(StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    [ProducesResponseType(StatusCodes.Status409Conflict)]
    public async Task<IActionResult> GetOperationResult(string operationId)
    {
        var operation = await _operationStore.GetAsync(operationId);

        if (operation == null)
            return NotFound(new { Error = \"Operation not found\" });

        // Verify requestor
        if (operation.Requestor != User.Identity.Name && !User.IsInRole(\"Admin\"))
            return Forbid();

        // Check if operation completed
        if (operation.Status != OperationState.Completed)
        {
            return Conflict(new
            {
                Error = \"Operation not yet completed\",
                Status = operation.Status.ToString(),
                StatusUrl = $\"/api/operations/{operationId}\"
            });
        }

        // Retrieve result from result store
        var result = await _resultStore.GetAsync(operationId);

        if (result == null)
            return NotFound(new { Error = \"Result not found or expired\" });

        // Set cache headers for completed results
        Response.Headers.Add(\"Cache-Control\", \"private, max-age=86400\");
        Response.Headers.Add(\"ETag\", $\"\\\"{operationId}-result\\\"\");

        return Ok(result);
    }

    [HttpDelete(\"{operationId}\")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    public async Task<IActionResult> CancelOperation(string operationId)
    {
        var operation = await _operationStore.GetAsync(operationId);

        if (operation == null)
            return NotFound();

        // Verify requestor
        if (operation.Requestor != User.Identity.Name && !User.IsInRole(\"Admin\"))
            return Forbid();

        // Can only cancel operations that haven't completed
        if (operation.Status == OperationState.Completed || operation.Status == OperationState.Failed)
            return Conflict(new { Error = \"Cannot cancel completed operation\" });

        // Update status to cancelled
        operation.Status = OperationState.Cancelled;
        operation.CompletedAt = DateTime.UtcNow;
        await _operationStore.UpdateAsync(operation);

        return NoContent();
    }
}
```

**Step 3: Implement Background Worker**

```csharp
public class CredentialingWorker : BackgroundService
{
    private readonly ServiceBusProcessor _processor;
    private readonly IOperationStore _operationStore;
    private readonly IResultStore _resultStore;
    private readonly ICredentialingService _credentialingService;
    private readonly IWebhookService _webhookService;
    private readonly ILogger<CredentialingWorker> _logger;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _processor.ProcessMessageAsync += ProcessMessageHandler;
        _processor.ProcessErrorAsync += ErrorHandler;

        await _processor.StartProcessingAsync(stoppingToken);
    }

    private async Task ProcessMessageHandler(ProcessMessageEventArgs args)
    {
        var message = JsonSerializer.Deserialize<CredentialingMessage>(args.Message.Body.ToString());
        var operationId = message.OperationId;

        try
        {
            _logger.LogInformation($\"Processing credentialing operation {operationId}\");

            // Update status to Running
            await _operationStore.UpdateAsync(operationId, OperationState.Running, progress: 0);

            // Execute long-running credentialing checks
            var result = await _credentialingService.ProcessCredentialingAsync(
                message.Payload,
                progressCallback: async (progress) =>
                {
                    await _operationStore.UpdateProgressAsync(operationId, progress);
                },
                cancellationToken: CancellationToken.None);

            // Store result
            await _resultStore.SaveAsync(operationId, result);

            // Update status to Completed
            await _operationStore.UpdateAsync(operationId, OperationState.Completed, progress: 100);

            // Trigger webhook if configured
            var operation = await _operationStore.GetAsync(operationId);
            if (!string.IsNullOrEmpty(operation.CallbackUrl))
            {
                await _webhookService.DeliverAsync(operation.CallbackUrl, new WebhookPayload
                {
                    OperationId = operationId,
                    Status = \"Completed\",
                    ResultUrl = $\"/api/operations/{operationId}/result\",
                    CompletedAt = operation.CompletedAt.Value
                });
            }

            // Complete the message (remove from queue)
            await args.CompleteMessageAsync(args.Message);

            _logger.LogInformation($\"Completed credentialing operation {operationId}\");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $\"Error processing credentialing operation {operationId}\");

            // Update status to Failed
            await _operationStore.UpdateAsync(operationId, OperationState.Failed, error: new OperationError
            {
                Code = \"ProcessingError\",
                Message = ex.Message,
                Details = ex.StackTrace
            });

            // Dead-letter the message after max retries
            if (args.Message.DeliveryCount >= 3)
            {
                await args.DeadLetterMessageAsync(args.Message, \"MaxRetriesExceeded\", ex.Message);
            }
            else
            {
                // Abandon message for retry
                await args.AbandonMessageAsync(args.Message);
            }
        }
    }
}
```

**Step 4: Implement Client SDKs**

Provide client libraries abstracting polling complexity:

```csharp
// C# Client SDK
public class AsyncOperationClient
{
    private readonly HttpClient _httpClient;
    private readonly TimeSpan _pollingInterval;

    public AsyncOperationClient(HttpClient httpClient, TimeSpan? pollingInterval = null)
    {
        _httpClient = httpClient;
        _pollingInterval = pollingInterval ?? TimeSpan.FromSeconds(5);
    }

    public async Task<TResult> SubmitAndWaitAsync<TResult>(
        string endpoint,
        object payload,
        TimeSpan? timeout = null,
        IProgress<int>? progress = null,
        CancellationToken cancellationToken = default)
    {
        // Submit operation
        var response = await _httpClient.PostAsJsonAsync(endpoint, payload, cancellationToken);
        response.EnsureSuccessStatusCode();

        var acceptedResponse = await response.Content.ReadFromJsonAsync<OperationAcceptedResponse>();
        var operationId = acceptedResponse.OperationId;

        // Poll for completion
        var deadline = timeout.HasValue ? DateTime.UtcNow.Add(timeout.Value) : DateTime.MaxValue;

        while (DateTime.UtcNow < deadline)
        {
            cancellationToken.ThrowIfCancellationRequested();

            var statusResponse = await _httpClient.GetFromJsonAsync<OperationStatus>(
                acceptedResponse.StatusUrl, cancellationToken);

            // Report progress
            if (statusResponse.Progress.HasValue && progress != null)
            {
                progress.Report(statusResponse.Progress.Value);
            }

            // Check completion
            if (statusResponse.Status == \"Completed\")
            {
                var resultResponse = await _httpClient.GetFromJsonAsync<TResult>(
                    statusResponse.ResultUrl, cancellationToken);
                return resultResponse;
            }
            else if (statusResponse.Status == \"Failed\")
            {
                throw new OperationFailedException(statusResponse.Error);
            }

            // Wait before next poll
            await Task.Delay(_pollingInterval, cancellationToken);
        }

        throw new TimeoutException($\"Operation {operationId} did not complete within timeout\");
    }
}

