### Real-World Example 2: Member Health Summary Report Generation

**Context**: Gainwell Go mobile app requests comprehensive health summary requiring federated queries to multiple HIEs, claims aggregation from enterprise system, and SDOH screening results. Operation takes 45-90 seconds. Original synchronous implementation caused mobile app to freeze, battery drain, and high user abandonment.

**Implementation Strategy**:

1. **Submit request with progress tracking**:
```swift
// iOS Swift client
class HealthSummaryService {
    func requestHealthSummary(memberId: String) async throws -> String {
        let url = URL(string: "\(baseURL)/api/members/\(memberId)/health-summary")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"

        let (data, response) = try await URLSession.shared.data(for: request)

        guard let httpResponse = response as? HTTPURLResponse,
              httpResponse.statusCode == 202 else {
            throw HealthSummaryError.requestFailed
        }

        let acceptedResponse = try JSONDecoder().decode(
            OperationAcceptedResponse.self, from: data)
        return acceptedResponse.operationId
    }

    func pollStatus(operationId: String) -> AsyncStream<OperationStatus> {
        AsyncStream { continuation in
            Task {
                var completed = false
                while !completed {
                    let status = try await fetchStatus(operationId)
                    continuation.yield(status)

                    if status.status == "Completed" || status.status == "Failed" {
                        completed = true
                        continuation.finish()
                    } else {
                        try await Task.sleep(nanoseconds: 5_000_000_000)  // 5 seconds
                    }
                }
            }
        }
    }
}

// SwiftUI view
struct HealthSummaryView: View {
    @State private var operationId: String?
    @State private var progress: Int = 0
    @State private var summary: HealthSummary?

    var body: some View {
        VStack {
            if let summary = summary {
                HealthSummaryDetailView(summary: summary)
            } else {
                VStack {
                    ProgressView("Loading your health information...",
                                 value: Double(progress), total: 100)
                    Text("\(progress)% complete")
                    Button("Cancel") {
                        Task { await cancelOperation() }
                    }
                }
            }
        }
        .task {
            await loadHealthSummary()
        }
    }

    func loadHealthSummary() async {
        do {
            // Submit request
            operationId = try await healthService.requestHealthSummary(
                memberId: currentMemberId)

            // Poll for completion
            for await status in healthService.pollStatus(operationId: operationId!) {
                progress = status.progress ?? 0

                if status.status == "Completed" {
                    summary = try await healthService.fetchResult(operationId: operationId!)
                }
            }
        } catch {
            showError(error)
        }
    }
}
```

2. **Push notifications for completion** (optional enhancement):
